<script setup lang="ts">
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import FieldError from '../../../components/FieldError.vue';
import type { PageProps } from '../../../types';

interface Address { recipient_name: string | null; phone: string | null; country_code: string | null; region: string | null; city: string | null; district: string | null; address_line_1: string | null; address_line_2: string | null; postal_code: string | null; reference: string | null }
interface Reservation { id: string; location: string; code: string; quantity: number; status: string }
interface Item { id: string; product_name: string; variant_name: string | null; sku: string; quantity: number; base_unit_price: string; discount_unit_amount: string; final_unit_price: string; line_base_total: string; line_discount_total: string; line_total: string; promotion_name: string | null; reservations: Reservation[] }
interface History { id: string; from_status: string | null; to_status: string; reason: string | null; actor: string | null; created_at: string }
interface Order { id: string; order_number: string; checkout_session_id: string; cart_id: string | null; status: string; payment_status: string; fulfillment_status: string; currency: string; customer_name: string | null; email: string | null; phone: string | null; shipping: Address; billing: Address; delivery_type: string; subtotal_before_discounts: string; discount_total: string; subtotal: string; shipping_total: string; tax_total: string; grand_total: string; placed_at: string; cancelled_at: string | null; items: Item[]; history: History[] }
const props = defineProps<{ order: Order; canCancel: boolean }>();
const page = usePage<PageProps>();
const status = computed(() => page.props.status);
const serverErrors = computed(() => page.props.errors as Record<string, string | undefined>);
const form = useForm({ reason: '' });
const cancel = () => { if (window.confirm('Cancel this order and release its active reservations?')) form.post(`/admin/orders/${props.order.id}/cancel`, { preserveScroll: true }); };
const money = (amount: string) => `${props.order.currency} ${amount}`;
const addressLines = (address: Address): string[] => [address.recipient_name, address.phone, address.address_line_1, address.address_line_2, [address.district, address.city, address.region].filter(Boolean).join(', '), [address.country_code, address.postal_code].filter(Boolean).join(' '), address.reference].filter((line): line is string => Boolean(line));
const addressTypes: ('shipping' | 'billing')[] = ['shipping', 'billing'];
</script>

<template>
    <Head :title="`Order ${order.order_number}`" />
    <AdminLayout>
        <section>
            <div class="flex flex-wrap items-end justify-between gap-5"><div><p class="font-mono text-xs tracking-[0.2em] text-emerald-800 uppercase">{{ order.status }} / {{ order.payment_status }} / {{ order.fulfillment_status }}</p><h1 class="mt-4 text-4xl font-semibold tracking-[-0.04em] sm:text-6xl">{{ order.order_number }}</h1><p class="mt-3 text-sm text-[#637067]">Placed {{ new Date(order.placed_at).toLocaleString() }}</p></div><Link href="/admin/orders" class="border border-[#17211b] px-4 py-3 text-sm font-semibold">Back to orders</Link></div>
            <p v-if="status" class="mt-6 border border-emerald-700 bg-emerald-50 p-4 text-sm font-semibold text-emerald-900">{{ status }}</p>
            <div class="mt-8 grid gap-4 sm:grid-cols-3"><article v-for="item in [['Order', order.status], ['Payment', order.payment_status], ['Fulfillment', order.fulfillment_status]]" :key="item[0]" class="border border-[#17211b]/15 bg-[#f8f5ed] p-5"><p class="text-xs uppercase text-[#637067]">{{ item[0] }}</p><p class="mt-2 font-mono text-lg font-semibold">{{ item[1] }}</p></article></div>
            <div class="mt-8 grid gap-5 lg:grid-cols-3"><article class="border border-[#17211b]/15 bg-white p-5"><h2 class="text-xl font-semibold">Buyer snapshot</h2><p class="mt-4">{{ order.customer_name ?? 'Guest' }}</p><p>{{ order.email ?? 'No email' }}</p><p>{{ order.phone ?? 'No phone' }}</p></article><article v-for="type in addressTypes" :key="type" class="border border-[#17211b]/15 bg-white p-5"><h2 class="text-xl font-semibold capitalize">{{ type }} snapshot</h2><p v-if="!addressLines(order[type]).length" class="mt-4 text-[#637067]">Not provided</p><p v-for="line in addressLines(order[type])" :key="line" class="mt-1 first:mt-4">{{ line }}</p></article></div>
            <section class="mt-10"><h2 class="text-3xl font-semibold">Order items</h2><div class="mt-5 grid gap-4"><article v-for="item in order.items" :key="item.id" class="border border-[#17211b]/15 bg-[#f8f5ed] p-5"><div class="flex flex-wrap justify-between gap-5"><div><h3 class="text-xl font-semibold">{{ item.product_name }}</h3><p class="text-sm text-[#637067]">{{ item.variant_name ?? 'Default variant' }} / {{ item.sku }} / Qty {{ item.quantity }}</p><p v-if="item.promotion_name" class="mt-2 text-sm font-semibold text-emerald-800">{{ item.promotion_name }}</p></div><dl class="grid grid-cols-3 gap-5 text-sm"><div><dt>Base</dt><dd class="font-mono">{{ money(item.base_unit_price) }}</dd></div><div><dt>Discount</dt><dd class="font-mono">{{ money(item.discount_unit_amount) }}</dd></div><div><dt>Line total</dt><dd class="font-mono font-semibold">{{ money(item.line_total) }}</dd></div></dl></div><div class="mt-4 flex flex-wrap gap-2"><span v-for="reservation in item.reservations" :key="reservation.id" class="bg-emerald-100 px-3 py-1 text-xs font-semibold">{{ reservation.code }}: {{ reservation.quantity }} ({{ reservation.status }})</span></div></article></div></section>
            <section class="mt-10 grid gap-6 lg:grid-cols-2"><article class="border border-[#17211b]/15 bg-white p-6"><h2 class="text-2xl font-semibold">Definitive totals</h2><dl class="mt-5 grid gap-3"><div v-for="row in [['Before discounts', order.subtotal_before_discounts], ['Discount', order.discount_total], ['Subtotal', order.subtotal], ['Shipping', order.shipping_total], ['Tax', order.tax_total], ['Grand total', order.grand_total]]" :key="row[0]" class="flex justify-between border-b pb-2"><dt>{{ row[0] }}</dt><dd class="font-mono font-semibold">{{ money(row[1]) }}</dd></div></dl></article><article class="border border-[#17211b]/15 bg-white p-6"><h2 class="text-2xl font-semibold">Status history</h2><ol class="mt-5 space-y-4"><li v-for="entry in order.history" :key="entry.id" class="border-l-2 border-emerald-700 pl-4"><p class="font-mono font-semibold">{{ entry.from_status ?? 'CREATED' }} → {{ entry.to_status }}</p><p class="text-sm text-[#637067]">{{ new Date(entry.created_at).toLocaleString() }} / {{ entry.actor ?? 'System' }}</p><p v-if="entry.reason" class="mt-1 text-sm">{{ entry.reason }}</p></li></ol></article></section>
            <form v-if="canCancel" class="mt-10 border border-red-800/30 bg-red-50 p-6" @submit.prevent="cancel"><h2 class="text-2xl font-semibold text-red-900">Cancel order</h2><p class="mt-2 text-sm text-red-900">This releases active reservations. It does not reopen the cart or checkout.</p><label class="mt-4 block text-sm font-semibold">Administrative reason<textarea v-model="form.reason" required maxlength="500" class="mt-2 min-h-24 w-full border border-red-800/40 bg-white px-3 py-2" /></label><FieldError :message="form.errors.reason ?? serverErrors.order" /><button :disabled="form.processing" class="mt-4 border border-red-900 px-5 py-3 text-sm font-semibold text-red-900">Cancel order</button></form>
        </section>
    </AdminLayout>
</template>
